SELECT cs.id, cs.schedule_date, cs.employee_id, cs.employee_name, u.position as employee_role, u.phonenum as employee_phone, cs.shift_type, cs.start_time, cs.end_time, cs.work_hours, cs.work_area, cs.status, cs.priority, cs.notes, cs.create_time, cu.username as create_user_name FROM jsh_cloisonne_schedule cs LEFT JOIN jsh_user u ON cs.employee_id = u.id AND u.delete_flag = '0' LEFT JOIN jsh_user cu ON cs.create_user = cu.id AND cu.delete_flag = '0' WHERE cs.delete_flag = '0' AND cs.tenant_id = #{tenantId}
AND cs.schedule_date >= #{startDate}
AND cs.schedule_date <= #{endDate}
AND cs.employee_id = #{employeeId}
AND cs.shift_type = #{shiftType}
AND cs.status = #{status}
ORDER BY cs.schedule_date DESC, cs.start_time ASC

SELECT COUNT(*) as total_schedules, COUNT(DISTINCT employee_id) as statistics_count, SUM(work_hours) as total_work_hours, AVG(work_hours) as avg_work_hours, SUM(CASE WHEN status = 'normal' THEN 1 ELSE 0 END) as normal_count, SUM(CASE WHEN status = 'leave' THEN 1 ELSE 0 END) as leave_count, SUM(CASE WHEN status = 'swap' THEN 1 ELSE 0 END) as swap_count, SUM(CASE WHEN status = 'absent' THEN 1 ELSE 0 END) as absent_count, ROUND(SUM(CASE WHEN status = 'normal' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) as attendance_rate FROM jsh_cloisonne_schedule WHERE delete_flag = '0' AND tenant_id = #{tenantId}
AND schedule_date >= #{startDate}
AND schedule_date <= #{endDate}

SELECT cs.employee_id, cs.employee_name, COUNT(*) as total_schedules, SUM(cs.work_hours) as total_work_hours, AVG(cs.work_hours) as avg_work_hours, SUM(CASE WHEN cs.status = 'normal' THEN 1 ELSE 0 END) as normal_count, SUM(CASE WHEN cs.status = 'leave' THEN 1 ELSE 0 END) as leave_count, SUM(CASE WHEN cs.status = 'swap' THEN 1 ELSE 0 END) as swap_count, SUM(CASE WHEN cs.status = 'absent' THEN 1 ELSE 0 END) as absent_count, ROUND(SUM(CASE WHEN cs.status = 'normal' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) as attendance_rate FROM jsh_cloisonne_schedule cs WHERE cs.delete_flag = '0' AND cs.tenant_id = #{tenantId}
AND cs.schedule_date >= #{startDate}
AND cs.schedule_date <= #{endDate}
GROUP BY cs.employee_id, cs.employee_name ORDER BY total_work_hours DESC

SELECT schedule_date as statistics_date, COUNT(*) as statistics_count, SUM(work_hours) as statistics_value FROM jsh_cloisonne_schedule WHERE delete_flag = '0' AND tenant_id = #{tenantId}
AND schedule_date >= #{startDate}
AND schedule_date <= #{endDate}
GROUP BY schedule_date ORDER BY schedule_date ASC

SELECT shift_type as statistics_name, COUNT(*) as statistics_count, SUM(work_hours) as statistics_value FROM jsh_cloisonne_schedule WHERE delete_flag = '0' AND tenant_id = #{tenantId}
AND schedule_date >= #{startDate}
AND schedule_date <= #{endDate}
GROUP BY shift_type ORDER BY statistics_count DESC

SELECT COUNT(*)
FROM jsh_cloisonne_schedule
WHERE delete_flag = '0'
AND tenant_id = #{tenantId}
AND employee_id = #{employeeId}
AND schedule_date = #{scheduleDate}

    AND id != #{excludeId}

